{"script":"var ratingBars = document.querySelectorAll('[data-testid="rating-bar"]');
var results = [];
ratingBars.forEach(function(bar) {
  var labelEl = bar.querySelector('p, [class*="label"], [class*="stars"]');
  var percentEl = bar.querySelector('[class*="percent"], [class*="Percent"]');
  results.push({html: bar.outerHTML.substring(0, 300)});
});
// Also try to find rating info via text
var text = document.body.innerText;
var lines = text.split('\n');
var ratingInfo = [];
for (var i = 0; i < lines.length; i++) {
  if (lines[i].match(/[1-5]\s*(星|Star)/i) || lines[i].match(/^\d+\.\d+%$/)) {
    ratingInfo.push(lines[i]);
  }
}
return {ratingInfo: ratingInfo.slice(0, 30), rawResults: results};
"}

